4. Path: `p1` allows us to extract nodes (`e3`) from the relationship between players and the team.
5. Constraint: `e1.salary > MAX(e3.salary)` AND `e2.name = 'Rayo Vallecano'`.

One detail: The `SCALAR_AGGREGATE` needs a `LIST`. A `LIST` can be created from `nodes_of` a path. 

```json
[
  {
    "target": [ "e1" ],
    "entities": [
      { "id": "e1", "type": "Footballer" },
      { "id": "e2", "type": "Team" },
      { "id": "e3", "type": "Footballer" }
    ],
    "relationships": [
      { "id": "r1", "role": "plays_for", "from": "e3", "to": "e2" }
    ],
    "paths": [
      { "id": "p1", "start": "e3", "end": "e2", "roles": ["plays_for"] }
    ],
    "constraint": {
      "and_conditions": [
        {
          "left": { "attribute_name": "salary", "of": "e1" },
          "operator": ">",
          "right": {
            "list": {
              "list": { "nodes_of": "p1", "node_id": "e3" }
            },
            "map_expression": { "attribute_name": "salary", "of": "e3" },
            "aggregate_kind": "MAX"
          }
        },
        {
          "left": { "attribute_name": "name", "of": "e2" },
          "operator": "=",
          "right": "Rayo Vallecano"
        }
      ]
    }
  }
]
```
